const key = $env.JELLYSEERR_API_KEY;
if (!key) throw new Error('JELLYSEERR_API_KEY is not configured');

const response = await this.helpers.httpRequest({
  method: 'GET',
  url: 'http://127.0.0.1:8423/api/v1/request',
  qs: {take: 100, skip: 0, sort: 'added'},
  headers: {'X-Api-Key': key},
  json: true,
});

const state = $getWorkflowStaticData('global');
const current = Object.fromEntries(
  (response.results ?? []).map((request) => [
    String(request.id),
    {
      requestStatus: request.status,
      mediaStatus: request.media?.status ?? null,
      type: request.type,
      tmdbId: request.media?.tmdbId ?? null,
      requester: request.requestedBy?.displayName ?? request.requestedBy?.email ?? 'unknown',
      mediaUrl: request.media?.mediaUrl ?? null,
    },
  ]),
);

if (!state.requests) {
  state.requests = current;
  return [];
}

const requestLabel = {1: 'pending approval', 2: 'approved', 3: 'declined', 4: 'failed', 5: 'completed'};
const mediaLabel = {1: 'unknown', 2: 'pending', 3: 'processing', 4: 'partly available', 5: 'available'};
const changes = [];
for (const [id, item] of Object.entries(current)) {
  const previous = state.requests[id];
  if (!previous) {
    changes.push({id, item, isNew: true, text: `new request, ${requestLabel[item.requestStatus] ?? item.requestStatus}`});
  } else if (previous.requestStatus !== item.requestStatus || previous.mediaStatus !== item.mediaStatus) {
    changes.push({
      id,
      item,
      text: `${requestLabel[previous.requestStatus] ?? previous.requestStatus} to ${requestLabel[item.requestStatus] ?? item.requestStatus}; media ${mediaLabel[item.mediaStatus] ?? item.mediaStatus}`,
    });
  }
}
if (!changes.length) return [];

return [{json: {nextState: current, changes}}];

const nextState = $('Check request changes').first().json.nextState;
const state = $getWorkflowStaticData('global');
state.requests = nextState;
return $input.all();

// Notify only when a newly submitted request enters the tracker. Availability
// changes are useful in Jellyseerr's request list, but are not a new request.
const { changes = [], nextState } = $input.first().json;
const submitted = changes.filter((change) => change.isNew);
if (submitted.length === 0) {
  $getWorkflowStaticData('global').requests = nextState;
  return [];
}

const key = $env.JELLYSEERR_API_KEY;
const titleOf = async (item, id) => {
  const fallback = `${item?.type === "tv" ? "Serie" : "Film"} #${item?.tmdbId ?? id}`;
  if (!key || !item?.tmdbId) return fallback;
  try {
    const details = await this.helpers.httpRequest({
      method: "GET",
      url: `http://127.0.0.1:8423/api/v1/${item.type === "tv" ? "tv" : "movie"}/${item.tmdbId}`,
      headers: { "X-Api-Key": key },
      json: true,
    });
    return details?.title || details?.name || fallback;
  } catch {
    return fallback;
  }
};

const labels = [];
for (const change of submitted) labels.push(await titleOf(change.item, change.id));
return [{json: {
  event: true,
  source: "jellyseerr",
  severity: "info",
  title: labels.length === 1 ? `New Jellyseerr request: ${labels[0]}` : `${labels.length} new Jellyseerr requests`,
  message: labels.join("\n"),
  fingerprint: `jellyseerr:new-request:${submitted.map((change) => change.id).sort().join(",")}`,
  url: submitted[0]?.item?.mediaUrl ?? null,
}}];
